using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace SharpFFI.Generators.Core;

[Generator(LanguageNames.CSharp)]
public class AnnotationsGenerator : IIncrementalGenerator
{
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static context =>
        {
            const string attributeCode = """
                                         // <auto-generated />
                                         
                                         using System;

                                         namespace SharpFFI.Annotations;
                                          
                                         [AttributeUsage(AttributeTargets.Struct)]
                                         internal class HandleAttribute : Attribute;
                                         
                                         [AttributeUsage(AttributeTargets.Struct)]
                                         internal class FixedStringAttribute : Attribute;
                                         """;

            context.AddSource("SharpFFI.Annotations.g.cs", SourceText.From(attributeCode, Encoding.UTF8));
        });
    }
}